SO.jigsaw = { start(el, o) { const N = Math.min(8, 2 + Math.ceil(o.level / 1.6)), img = sceneArt(600, 450); let order = shuf([...Array(N * N).keys()]), sel = -1, moves = 0, over = false; const tm = timer();
  const draw = () => { el.innerHTML = `<div class="jig" style="grid-template-columns:repeat(${N},1fr)">${order.map((p, k) => `<button data-k="${k}" class="${sel === k ? 'sel' : ''} ${p === k ? 'ok' : ''}" style="background-image:url(${img});background-size:${N * 100}% ${N * 100}%;background-position:${(p % N) / (N - 1) * 100}% ${((p / N | 0) / (N - 1)) * 100}%"></button>`).join('')}</div><p class="muted small center">Tap two pieces to swap them. Moves ${moves} · ${order.filter((p, k) => p === k).length}/${N * N} in place</p><details><summary>Peek at the picture</summary><img src="${img}" alt="" style="width:200px;border-radius:8px"></details>`; };
  el.addEventListener('click', e => { const b = e.target.closest('[data-k]'); if (!b || over) return; const k = +b.dataset.k; if (sel < 0) sel = k; else { [order[sel], order[k]] = [order[k], order[sel]]; sel = -1; moves++; beep(500, .03); if (order.every((p, i) => p === i)) { over = true; soloEnd(o, Math.max(50, N * N * 30 * o.level / 3 - moves * 2 + Math.max(0, 600 - tm()) | 0), true); } } draw(); });
  draw(); return () => {}; } };

// ---------- Maze Escape ----------
SO.maze = { start(el, o) { const N = 8 + o.level * 2, S = Math.floor(600 / N), [cv, g] = canvas(el, N * S, N * S), walls = [...Array(N * N)].map(() => [1, 1, 1, 1]), seen = new Set([0]), st = [0];
  while (st.length) { const i = st[st.length - 1], r = i / N | 0, c = i % N, nb = [[r - 1, c, 0, 2], [r, c + 1, 1, 3], [r + 1, c, 2, 0], [r, c - 1, 3, 1]].filter(([a, b]) => a >= 0 && a < N && b >= 0 && b < N && !seen.has(a * N + b)); if (!nb.length) { st.pop(); continue; } const [a, b, w1, w2] = nb[R(nb.length)], j = a * N + b; walls[i][w1] = 0; walls[j][w2] = 0; seen.add(j); st.push(j); }
  let p = 0, over = false, trail = new Set([0]); const tm = timer(), limit = N * N * 1.2 | 0;
  const draw = () => { g.fillStyle = '#0b2e22'; g.fillRect(0, 0, N * S, N * S); g.fillStyle = '#ffc23d33'; trail.forEach(i => g.fillRect((i % N) * S, (i / N | 0) * S, S, S)); g.fillStyle = '#ff5a3c'; g.fillRect((N - 1) * S + 3, (N - 1) * S + 3, S - 6, S - 6);
    g.strokeStyle = '#e9f1ec'; g.lineWidth = 2; g.beginPath(); walls.forEach((w, i) => { const x = (i % N) * S, y = (i / N | 0) * S; if (w[0]) { g.moveTo(x, y); g.lineTo(x + S, y); } if (w[1]) { g.moveTo(x + S, y); g.lineTo(x + S, y + S); } if (w[2]) { g.moveTo(x, y + S); g.lineTo(x + S, y + S); } if (w[3]) { g.moveTo(x, y); g.lineTo(x, y + S); } }); g.stroke();
    g.fillStyle = '#ffc23d'; g.beginPath(); g.arc((p % N) * S + S / 2, (p / N | 0) * S + S / 2, S / 3, 0, 7); g.fill(); hud(el, `Time ${tm()}s · reach the red square`); };
  const go = k => { if (over) return; const d = { U: [0, -N], R: [1, 1], D: [2, N], L: [3, -1] }[k]; if (!d || walls[p][d[0]]) return; p += d[1]; trail.add(p); draw(); if (p === N * N - 1) { over = true; beep(880, .2); soloEnd(o, Math.max(50, (limit - tm()) * o.level), true); } };
  const un = keys(go); swipe(cv, go); pad(el, ['L', 'U', 'D', 'R'], go); const iv = setInterval(draw, 1000); draw(); return () => { un(); clearInterval(iv); }; } };

// ---------- Tangram ----------
const TAN = [[[0, 0], [4, 0], [2, 2]], [[0, 0], [2, 2], [0, 4]], [[4, 2], [4, 4], [2, 4]], [[4, 0], [4, 2], [3, 1]], [[2, 2], [3, 1], [4, 2], [3, 3]], [[2, 2], [3, 3], [1, 3]], [[1, 3], [3, 3], [2, 4], [0, 4]]].map(pg => { const cx = sum(pg.map(p => p[0])) / pg.length, cy = sum(pg.map(p => p[1])) / pg.length; return { pg: pg.map(([x, y]) => [x - cx, y - cy]), home: [cx, cy] }; });
