const tanPts = (k, x, y, a, f) => TAN[k].pg.map(([px, py]) => { const fx = f ? -px : px, c = Math.cos(a * Math.PI / 4), s = Math.sin(a * Math.PI / 4); return [x + fx * c - py * s, y + fx * s + py * c]; });
function tanRaster(places, U, W) { const c = document.createElement('canvas'); c.width = c.height = W; const g = c.getContext('2d'); g.fillStyle = '#000'; for (const p of places) { const pts = tanPts(p.k, p.x, p.y, p.a, p.f); g.beginPath(); pts.forEach(([x, y], i) => (i ? g.lineTo : g.moveTo).call(g, x * U, y * U)); g.closePath(); g.fill(); } return g.getImageData(0, 0, W, W).data; }
