  Words.load().then(() => { if (!over) { next(); iv = setInterval(() => { if (over) return; left--; const t = el.querySelector('.scr p b:last-child'); if (t) t.textContent = left + 's'; if (left <= 0) { toast('Time! It was ' + word.toUpperCase()); next(); } }, 1000); } });
