  const rows = [...new Set([...Array(S * S).keys()].filter(i => used[i]).map(i => i / S | 0))], cols = [...new Set([...Array(S * S).keys()].filter(i => used[i]).map(i => i % S))], r0 = Math.min(...rows), r1 = Math.max(...rows), c0 = Math.min(...cols), c1 = Math.max(...cols);
