    let h = ''; for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) { const i = r * S + c; h += used[i] ? `<button data-i="${i}" class="${sel === i ? 'sel' : inCur.has(i) ? 'rel' : ''} ${checked && inp[i] && inp[i] !== P.g[i] ? 'bad' : ''}">${num[i] ? `<small>${num[i]}</small>` : ''}${(inp[i] || '').toUpperCase()}</button>` : '<i></i>'; }
    const list = d => P.placed.filter(p => p.d === d).sort((a, b) => a.n - b.n).map(p => `<li class="${cur === p ? 'on' : ''}" data-w="${P.placed.indexOf(p)}"><b>${p.n}</b> ${esc(p.clue)} (${p.w.length})</li>`).join('');
    el.innerHTML = `<div class="xw"><div class="xwg" style="grid-template-columns:repeat(${c1 - c0 + 1},1fr)">${h}</div><div class="xwc"><h4>Across</h4><ol>${list(0)}</ol><h4>Down</h4><ol>${list(1)}</ol></div></div><input class="xwin" id="xwin" autocomplete="off" autocapitalize="none" aria-label="Type letters"><div class="row-btns"><button class="btn sm" data-a="check">Check</button><button class="btn sm" data-a="reveal">Reveal a letter</button></div>`;
