  let reveals = 0; const step = back => { const cur = wordOf(sel, dir) || wordOf(sel, 1 - dir); if (!cur) return; dir = cur.d; const nx = sel + (back ? -1 : 1) * (dir ? S : 1); if (used[nx] && wordOf(nx, dir) === cur) sel = nx; };
