  const un = keys(k => { kd[k] = 1; }, k => { kd[k] = 0; }); pad(el, ['L', 'U', 'R', 'A'], k => kd[k] = 1, k => kd[k] = 0); const wrap = p => { p.x = (p.x + W) % W; p.y = (p.y + H) % H; };
